package com.driftdroid.android

import android.app.Activity
import android.content.Intent
import android.net.Uri
import android.widget.Toast
import java.io.File

/**
 * Lossless Scaling frame generation for Mario Kart Wii and Retro Rewind: the 120 FPS slots of the
 * frame interpolation are generated by libbloodframe.so from the player's own Lossless.dll
 * (Lossless Scaling on Steam) instead of the built-in interpolation. WiiDS ships no part of it;
 * the DLL is imported here into the app's private files and named in Config.toml [video]
 * (frame_generation, lsfg_dll, frame_interpolation_fps), which the runtime reads at startup and
 * the in-game Display page changes later (runtime/src/settings_overlay.cpp).
 */
object FrameGenerationSettings {
    const val REQUEST_CODE_PICK_DLL = 9823

    private fun configFile(activity: Activity) = File(File(activity.filesDir, "WiiCompiled"), "Config.toml")

    private fun dllFile(activity: Activity) = File(File(activity.filesDir, "WiiCompiled"), "Lossless.dll")

    private fun readKey(activity: Activity, key: String): String? =
        runCatching {
            configFile(activity).takeIf { it.isFile }?.readLines()
                ?.firstOrNull { it.trimStart().startsWith("$key ") || it.trimStart().startsWith("$key=") }
                ?.substringAfter('=')?.trim()?.trim('"')
        }.getOrNull()

    /** Sets each key under [video] (a null value removes it), leaving every other line alone. */
    private fun write(activity: Activity, values: Map<String, String?>): Boolean =
        runCatching {
            val file = configFile(activity)
            file.parentFile?.mkdirs()
            val lines = if (file.isFile) file.readLines().toMutableList() else mutableListOf()
            for ((key, value) in values) {
                val existing = lines.indexOfFirst { it.trimStart().startsWith("$key ") || it.trimStart().startsWith("$key=") }
                if (value == null) {
                    if (existing >= 0) lines.removeAt(existing)
                    continue
                }
                if (existing >= 0) {
                    lines[existing] = "$key = $value"
                    continue
                }
                val section = lines.indexOfFirst { it.trim() == "[video]" }
                if (section >= 0) {
                    lines.add(section + 1, "$key = $value")
                } else {
                    if (lines.isNotEmpty() && lines.last().isNotBlank()) lines.add("")
                    lines.add("[video]")
                    lines.add("$key = $value")
                }
            }
            AtomicConfigFile.writeText(file, lines.joinToString("\n") + "\n")
        }.isSuccess

    private fun quoted(value: String) = "\"" + value.replace("\\", "\\\\").replace("\"", "\\\"") + "\""

    private fun dllInstalled(activity: Activity): Boolean {
        val path = readKey(activity, "lsfg_dll") ?: return false
        return File(path).isFile
    }

    fun show(activity: Activity) {
        val lsfg = readKey(activity, "frame_generation") == "lsfg"
        val installed = dllInstalled(activity)
        val labels = arrayOf(
            if (BuildConfig.THOR_BUILD) "Interpolation (built in)" else "Interpolation (built in)\nRedraws the scene between frames.",
            if (installed) "Lossless Scaling\nUsing your Lossless.dll." else "Lossless Scaling\nChoose your Lossless.dll first.",
        )
        var selected = if (lsfg) 1 else 0
        val dialog = ThorDialogs.builder(activity)
            .setTitle("Frame generation (Mario Kart Wii)")
            .setSingleChoiceItems(labels, selected) { _, which -> selected = which }
            .setNegativeButton("Cancel", null)
            .setNeutralButton(if (installed) "Replace DLL" else "Choose Lossless.dll") { _, _ -> pickDll(activity) }
            .setPositiveButton("Save") { _, _ ->
                val chooseLsfg = selected == 1
                if (chooseLsfg && !dllInstalled(activity)) {
                    pickDll(activity)
                    return@setPositiveButton
                }
                val values = mutableMapOf<String, String?>(
                    "frame_generation" to quoted(if (chooseLsfg) "lsfg" else "interpolation"),
                )
                // Lossless Scaling needs the inserted slots: 120 FPS on the Thor's 120 Hz screens.
                if (chooseLsfg && (readKey(activity, "frame_interpolation_fps")?.toIntOrNull() ?: 0) == 0) {
                    values["frame_interpolation_fps"] = "120"
                }
                val ok = write(activity, values)
                Toast.makeText(
                    activity,
                    when {
                        !ok -> "Could not save the frame generation choice."
                        chooseLsfg -> "Lossless Scaling at 120 FPS from the next race. Change it in the game's Display settings."
                        else -> "Built-in interpolation selected."
                    },
                    Toast.LENGTH_LONG,
                ).show()
            }
            .create()
        dialog.show()
    }

    private fun pickDll(activity: Activity) {
        val intent = Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*")
        runCatching { activity.startActivityForResult(intent, REQUEST_CODE_PICK_DLL) }
    }

    /** Call from the activity's onActivityResult for [REQUEST_CODE_PICK_DLL]. */
    fun onDllPicked(activity: Activity, uri: Uri?) {
        if (uri == null) return
        Thread {
            val error = runCatching { install(activity, uri) }.exceptionOrNull()?.let { it.message ?: it.toString() }
            activity.runOnUiThread {
                if (error != null) {
                    ThorDialogs.builder(activity)
                        .setTitle("Lossless.dll not imported")
                        .setMessage(error)
                        .setPositiveButton("OK", null)
                        .show()
                } else {
                    Toast.makeText(activity, "Lossless.dll imported.", Toast.LENGTH_SHORT).show()
                    show(activity)
                }
            }
        }.start()
    }

    private fun install(activity: Activity, uri: Uri) {
        val target = dllFile(activity)
        target.parentFile?.mkdirs()
        val staging = File(target.parentFile, "Lossless.dll.part")
        try {
            val input = activity.contentResolver.openInputStream(uri) ?: error("Could not open that file.")
            input.use { stream -> staging.outputStream().use { stream.copyTo(it) } }
            // A Windows DLL starts with "MZ"; the real one is several megabytes of shaders.
            val header = staging.inputStream().use { val b = ByteArray(2); it.read(b); b }
            if (header[0] != 'M'.code.toByte() || header[1] != 'Z'.code.toByte() || staging.length() < 1_000_000) {
                error("That is not Lossless.dll. It is in the Lossless Scaling folder of your Steam library.")
            }
            if (!staging.renameTo(target)) error("Could not store the DLL.")
            if (!write(activity, mapOf("lsfg_dll" to quoted(target.absolutePath)))) error("Could not save the DLL's location.")
        } finally {
            staging.delete()
        }
    }
}
